<script>(()=>{let dirty=<?= $error?'true':'false' ?>;const form=document.getElementById('facility-form'),rows=[...form.querySelectorAll('.item')],q=document.getElementById('facility-search'),f=document.getElementById('selected-only');function refresh(){let visible=0,total=0;rows.forEach(r=>{const checked=r.querySelector('input').checked;if(checked)total++;r.hidden=!r.dataset.name.toLowerCase().includes(q.value.trim().toLowerCase())||(f.checked&&!checked);if(!r.hidden)visible++;});document.querySelectorAll('section').forEach(s=>{const items=[...s.querySelectorAll('.item')];s.hidden=!items.some(r=>!r.hidden);s.querySelector('.group-count').textContent=items.filter(r=>r.querySelector('input').checked).length+' / '+items.length;});document.getElementById('selected-total').textContent=total;document.getElementById('facility-empty').hidden=visible>0;}q.addEventListener('input',refresh);f.addEventListener('change',refresh);form.addEventListener('change',()=>{dirty=true;document.getElementById('save-status').textContent='변경한 내용을 저장해 주세요.';refresh();});form.addEventListener('submit',()=>dirty=false);window.buildingInfoRequestClose=()=>{if(!dirty||window.confirm('저장하지 않은 변경사항이 있습니다. 닫을까요?'))window.parent.postMessage({type:'building-info-close'},window.location.origin);};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});refresh();})();</script></body></html>
